    setVolume: (value) => invoke("player_set_volume", { value }),
    setLoop: (on) => invoke("player_set_loop", { on }),
    status: () => invoke("player_status", {}),

    // misc
    settings: (patch) => invoke("settings", { patch: patch || {} }),
    checkUpdate: () => invoke("check_update", {}),
    openLink: (url) => invoke("open_link", { url }),
    openDbFolder: () => invoke("open_db_folder", {}),
    copyPaths: async (ids) => {
      const text = await invoke("copy_paths", { ids });
      if (!text) return false;
      try {
        await navigator.clipboard.writeText(text);
        return true;
      } catch (e) {
        const ta = document.createElement("textarea");
        ta.value = text;
        ta.style.cssText = "position:fixed;top:-2000px;left:0;opacity:0";
        document.body.appendChild(ta);
        ta.select();
        let ok = false;
        try {
          ok = document.execCommand("copy");
        } catch (e2) {}
        ta.remove();
        return ok;
      }
    },
